.field.error .combobox .control:has(input:focus),.field.error .combobox.open .control{border-color:var(--foreground-negative-primary);box-shadow:0 0 0 4px var(--line-negative-focus)}
.field.sm .combobox .control{min-height:2rem;padding-top:1px;padding-bottom:1px;border-radius:var(--radius-sm)}
.field.sm .combobox .control input{height:1.75rem;font-size:var(--font-size-12);line-height:max(1rem,16px);letter-spacing:0.0252em}
.field.lg .combobox .control{min-height:3rem;padding-top:0.375rem;padding-bottom:0.375rem}
.field.lg .combobox .control input{height:2.125rem;font-size:var(--font-size-16);line-height:1.625rem;letter-spacing:0.0057em}
.field .affix:has(input:disabled){background:var(--surface-disable-primary);cursor:not-allowed}
.field .affix:has(input:read-only:not(:disabled)){background:var(--background-neutral-secondary)}
.field .affix span{color:var(--foreground-neutral-tertiary);font-size:var(--font-size-12);white-space:nowrap;line-height:max(1rem,16px);letter-spacing:0.0252em}
.field .counter{margin-left:auto;font-size:var(--font-size-12);color:var(--foreground-neutral-tertiary);line-height:max(1rem,16px);letter-spacing:0.0252em}
.field .row:where(:not(.radio-group)):where(:not(.checkbox-group)){display:flex;justify-content:space-between;align-items:baseline}
.field.slider-field{min-width:min(26rem,100%)}
.field.sm.timepicker .tp-btn{border-radius:var(--radius-sm)}
.field.error .checkbox input:not(:checked):not(:disabled),.field.error .radio input:not(:checked):not(:disabled){box-shadow:inset 0 0 0 1.5px var(--foreground-negative-primary)}
.dropdown.sm .trigger,.field.sm .dropdown .trigger{height:2rem;padding:0 0.625rem 0 0.75rem;font-size:var(--font-size-12);border-radius:var(--radius-sm);line-height:max(1rem,16px);letter-spacing:0.0252em}
.dropdown.lg .trigger,.field.lg .dropdown .trigger{height:3rem;padding:0 0.875rem 0 1rem;font-size:var(--font-size-16);line-height:1.625rem;letter-spacing:0.0057em}
.form .form-row .field{min-width:0}
.form .field{min-width:0}
.field .affix .num-btn{display:grid;place-items:center;flex:none;width:1.75rem;height:1.75rem;padding:0;border:0;border-radius:var(--radius-md);background:transparent;color:var(--foreground-neutral-secondary);cursor:pointer}
.field .affix .num-btn.down,.field .affix .num-btn.up{margin-right:-0.375rem}
