import { Radio } from "@jiran/ds-react";

export default function Example() {
  return <Radio name="rd">표준 모드</Radio>;
}

import { Radio } from "@jiran/ds-react";

export default function Example() {
  return (
    <>
      <Radio name="r1">Unchecked</Radio>
      <Radio name="r1" defaultChecked>Checked</Radio>
      <Radio name="r2" disabled>Disabled</Radio>
      <Radio name="r3" defaultChecked disabled>Disabled checked</Radio>
    </>
  );
}

import { Radio, RadioGroup } from "@jiran/ds-react";

export default function Example() {
  return (
    <RadioGroup legend="탐지 시 동작" name="act" defaultValue="block">
      <Radio value="block" description="실행을 즉시 중단하고 관리자에게 알립니다">차단 후 알림</Radio>
      <Radio value="notify" description="기록과 알림만, 실행은 허용">알림만</Radio>
      <Radio value="log">기록만</Radio>
    </RadioGroup>
  );
}

import { Radio, RadioGroup } from "@jiran/ds-react";

export default function Example() {
  return (
    <RadioGroup row card name="plan" defaultValue="standard">
      <Radio value="standard" description="권장. 알려진 위협 차단">표준 모드</Radio>
      <Radio value="hardened" description="의심 행위까지 차단, 오탐 증가">강화 모드</Radio>
    </RadioGroup>
  );
}

import { Button, Form, FormActions, FormLegend, Radio, RadioGroup } from "@jiran/ds-react";

export default function Example() {
  return (
    <Form validate style={{ width: 360 }} onSubmit={(e) => e.preventDefault()}>
      <FormLegend />
      <RadioGroup legend="격리 해제 권한" required>
        <Radio value="sec">보안 관리자만</Radio>
        <Radio value="ops">보안 · 운영 관리자</Radio>
        <Radio value="all">모든 관리자</Radio>
      </RadioGroup>
      <FormActions>
        <Button type="submit">저장</Button>
      </FormActions>
    </Form>
  );
}

