import { Switch } from "@jiran/ds-react";

export default function Example() {
  return <Switch>실시간 보호</Switch>;
}

import { Switch } from "@jiran/ds-react";

export default function Example() {
  return (
    <>
      <Switch>Off</Switch>
      <Switch defaultChecked>On</Switch>
      <Switch disabled>Disabled</Switch>
      <Switch defaultChecked disabled>Disabled on</Switch>
    </>
  );
}

import { Switch, ToastProvider } from "@jiran/ds-react";

const save = () => new Promise((resolve) => setTimeout(resolve, 900));
const fail = () => new Promise((_, reject) => setTimeout(reject, 900));

/** action 이 끝나야 바뀐다. false 를 돌려주면 그대로(확인 Popup 취소), 던지면 Toast 로 알린다 */
export default function Example() {
  return (
    <ToastProvider>
      <Switch defaultChecked action={save}>실시간 보호</Switch>
      <Switch action={fail} errorMessage="정책 서버에 연결하지 못했습니다. 잠시 후 다시 시도하세요.">USB 자동 검사</Switch>
      <Switch defaultChecked busy>웹 필터</Switch>
    </ToastProvider>
  );
}

import { Switch } from "@jiran/ds-react";

export default function Example() {
  return (
    <>
      <Switch size="sm" defaultChecked>Small</Switch>
      <Switch labelLeft defaultChecked>라벨 왼쪽</Switch>
    </>
  );
}

import { Setting, SettingsSection, Switch } from "@jiran/ds-react";

export default function Example() {
  return (
    <SettingsSection style={{ maxWidth: 560 }}>
      <Setting title="실시간 보호" description="파일 실행 시 즉시 검사합니다">
        <Switch defaultChecked aria-label="실시간 보호" />
      </Setting>
      <Setting title="USB 자동 검사" description="연결된 저장장치를 검사합니다">
        <Switch aria-label="USB 자동 검사" />
      </Setting>
      <Setting title="원격 제어" description="보안 관리자만 바꿀 수 있습니다">
        <Switch disabled aria-label="원격 제어" />
      </Setting>
    </SettingsSection>
  );
}

