  );
}

import { Select } from "@jiran/ds-react";

const FILTER = [
  { value: "all", label: "전체" },
  { value: "critical", label: "Critical" },
  { value: "high", label: "High" },
  { value: "medium", label: "Medium" },
];
const APPROVERS = [
  { value: "", label: "선택 안 함" },
  { value: "kim", label: "김보안" },
  { value: "lee", label: "이인프라" },
  { value: "park", label: "박개발" },
];

export default function Example() {
  return (
    <>
      <Select options={FILTER} defaultValue="all" label="심각도 필터" keepMounted />
      <Select options={APPROVERS} placeholder="승인자 선택" label="승인자" keepMounted />
    </>
  );
}

import { Select } from "@jiran/ds-react";

export default function Example() {
  return (
    <>
      <Select options={[]} status="loading" placeholder="그룹 선택" label="불러오는 중" defaultOpen />
      <Select options={[]} status="error" onRetry={() => {}} placeholder="그룹 선택" label="불러오기 실패" defaultOpen />
      <Select options={[]} status="empty" placeholder="그룹 선택" label="항목 없음" defaultOpen />
    </>
  );
}

import { Button, Field, Form, FormActions, FormLegend, Select } from "@jiran/ds-react";

const GROUPS = [
  { value: "sales", label: "영업팀" },
  { value: "dev", label: "개발팀" },
  { value: "sec", label: "보안팀" },
];
const APPROVERS = [
  { value: "", label: "선택 안 함" },
  { value: "kim", label: "김보안" },
  { value: "lee", label: "이인프라" },
];

export default function Example() {
  return (
    <Form validate style={{ width: 360 }} onSubmit={(e) => e.preventDefault()}>
      <FormLegend />
      <Field label="적용 그룹" required>
        <Select name="group" required options={GROUPS} placeholder="그룹 선택" label="적용 그룹" keepMounted />
      </Field>
      <Field label="승인자">
        <Select name="approver" options={APPROVERS} placeholder="승인자 선택" label="승인자" keepMounted />
      </Field>
      <FormActions>
        <Button type="submit">정책 저장</Button>
      </FormActions>
    </Form>
  );
}

