/* JS Design System v0.9 · .accordion, .accordion-group · 토큰(var(--*))은 assets/style.css :root 참고 */
.accordion{border:1px solid var(--line-neutral-secondary);border-radius:var(--radius-lg);background:var(--surface-elevated-primary);width:100%;interpolate-size:allow-keywords;line-height:1.6}
