.accordion[open] summary{border-bottom-left-radius:0;border-bottom-right-radius:0}
.accordion:where(:not(.disabled)) summary:hover{background:var(--surface-neutral-secondary)}
.accordion summary::-webkit-details-marker{display:none}
.accordion summary::after{content:"";width:1rem;height:1rem;flex:none;background:var(--foreground-neutral-secondary);-webkit-mask:url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%2224%22 height=%2224%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke=%22black%22 stroke-width=%222%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22 %3E%3Cpath d=%22M6 9l6 6l6 -6%22 /%3E%3C/svg%3E") center/contain no-repeat;mask:url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%2224%22 height=%2224%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke=%22black%22 stroke-width=%222%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22 %3E%3Cpath d=%22M6 9l6 6l6 -6%22 /%3E%3C/svg%3E") center/contain no-repeat;transition:transform var(--motion-fast);margin-left:auto}
.accordion summary:has(>small)::after{margin-left:0}
.accordion[open] summary::after{transform:rotate(180deg)}
.accordion summary small{font-weight:500;color:var(--foreground-neutral-tertiary);margin-left:auto;font-size:var(--font-size-12);line-height:max(1rem,16px);letter-spacing:0.0252em}
.accordion summary>svg{flex:none;width:1.125rem;height:1.125rem}
.accordion .body{padding:0 1.25rem 1rem;font-size:var(--font-size-14);color:var(--foreground-neutral-secondary);line-height:1.375rem;letter-spacing:0.0145em}
.accordion.outline{border-color:var(--line-neutral-secondary)}
.accordion.md summary{padding:0.875rem 1.25rem;font-size:var(--font-size-16);line-height:1.5rem;letter-spacing:0.0057em}
.accordion.md .body{padding:0 1.25rem 1rem;font-size:var(--font-size-14);line-height:1.375rem;letter-spacing:0.0145em}
.accordion.sm summary{padding:0.5625rem 1rem;font-size:var(--font-size-14);line-height:1.375rem;letter-spacing:0.0145em}
.accordion.sm summary>svg{width:1rem;height:1rem}
.accordion.sm .body{padding:0 1rem 0.75rem;font-size:var(--font-size-12);line-height:max(1rem,16px);letter-spacing:0.0252em}
.accordion.lg summary{padding:1.0625rem 1.5rem;font-size:var(--font-size-18);line-height:1.625rem;letter-spacing:-0.002em}
.accordion.lg summary::after,.accordion.lg summary>svg{width:1.25rem;height:1.25rem}
.accordion.lg .body{padding:0 1.5rem 1.25rem}
.accordion.disabled>summary{cursor:not-allowed}
.accordion.disabled summary,.accordion.disabled summary small,.accordion.disabled .body{color:var(--foreground-disable-primary)}
.accordion.disabled summary::after{background:var(--foreground-disable-primary)}
.accordion.flat{border:0;border-radius:0;border-bottom:1px solid var(--line-neutral-secondary)}
.accordion.flat summary,.accordion.flat[open] summary{padding-left:0.25rem;padding-right:0.25rem;border-radius:var(--radius-md)}
.accordion.flat .body{padding-left:0.25rem;padding-right:0.25rem}
.accordion.flat:last-child{border-bottom:0}
.accordion-group{display:flex;flex-direction:column;gap:0.5rem;width:100%;line-height:1.6}
.accordion-group.flat{gap:0;background:var(--surface-elevated-primary);border:1px solid var(--line-neutral-secondary);padding:0 1.25rem;border-radius:var(--radius-lg)}
.accordion::details-content{height:0;overflow:hidden;transition:height var(--motion-base),content-visibility var(--motion-base);transition-behavior:allow-discrete}
