import { Button, Card, CardDesc, CardFoot, CardHead, CardTitle, Tag } from "@jiran/ds-react";

export default function Example() {
  return (
    <Card style={{ width: 360 }}>
      <CardHead>
        <CardTitle>라이선스</CardTitle>
        <Tag tone="ok">정상</Tag>
      </CardHead>
      <CardDesc>1,000석 중 842석 사용 중. 2026-12-31 만료.</CardDesc>
      <CardFoot>
        <Button variant="outline" color="assistive" size="sm">상세</Button>
        <Button size="sm">갱신</Button>
      </CardFoot>
    </Card>
  );
}

import { Card, CardDesc, CardHead, CardTitle, Tag } from "@jiran/ds-react";

/* md(기본) · sm — sm 은 밀도 높은 그리드에 */
export default function Example() {
  return (
    <div style={{ display: "flex", flexWrap: "wrap", gap: 20, alignItems: "flex-start" }}>
      <Card size="md" style={{ width: 300 }}>
        <CardHead>
          <CardTitle>md</CardTitle>
          <Tag tone="ok">정상</Tag>
        </CardHead>
        <CardDesc>padding 24 · gap 12 · 제목 16/24</CardDesc>
      </Card>
      <Card size="sm" style={{ width: 280 }}>
        <CardHead>
          <CardTitle>sm</CardTitle>
          <Tag tone="ok" size="sm">정상</Tag>
        </CardHead>
        <CardDesc>padding 16 · gap 8 · 제목 14/20</CardDesc>
      </Card>
    </div>
  );
}

import { Card, CardDesc, CardHead, CardMeta, CardTitle, Indicator, Tag } from "@jiran/ds-react";

/* 주변에 배경색(background/neutral/secondary)이 있을 때 — 보더 없이 면 색 차이로만. 흰 바탕 위에서는 쓰지 않는다 */
export default function Example() {
  return (
    <div style={{ background: "var(--background-neutral-secondary)", padding: 24, borderRadius: "var(--radius-lg)", display: "flex", flexWrap: "wrap", gap: 20, alignItems: "flex-start" }}>
      <Card variant="flat" style={{ width: "min(300px, 100%)" }}>
        <CardHead>
          <CardTitle>라이선스</CardTitle>
          <Tag tone="ok">정상</Tag>
        </CardHead>
        <CardDesc>1,000석 중 842석 사용 중. 2026-12-31 만료.</CardDesc>
      </Card>
      <Card variant="flat" style={{ width: "min(300px, 100%)" }}>
        <CardHead>
          <CardTitle>PC-2041</CardTitle>
          <Indicator tone="ok">온라인</Indicator>
        </CardHead>
        <CardMeta items={[{ label: "에이전트", value: "6.2.1" }, { label: "그룹", value: "개발팀" }, { label: "IP", value: "10.20.4.41" }]} />
      </Card>
    </div>
  );
}

import { Button, Card, CardHead, CardTitle, Empty, Icon } from "@jiran/ds-react";

/* 카드 틀과 헤더는 남기고 본문 자리만 바꾼다 */
export default function Example() {
  return (
    <div style={{ display: "flex", flexWrap: "wrap", gap: 20, alignItems: "flex-start" }}>
      <Card style={{ width: 320 }}>
        <CardHead>
          <CardTitle>최근 차단 이벤트</CardTitle>
