import { Button, Tooltip } from "@jiran/ds-react";

export default function Example() {
  return (
    <Tooltip content="목록을 다시 불러옵니다" show>
      <Button variant="outline" color="assistive">새로 고침</Button>
    </Tooltip>
  );
}

import { Button, Tooltip } from "@jiran/ds-react";

export default function Example() {
  return (
    <>
      <Tooltip content="위 (기본)" show><Button variant="outline" color="assistive">Top</Button></Tooltip>
      <Tooltip content="아래" position="bottom" show><Button variant="outline" color="assistive">Bottom</Button></Tooltip>
      <Tooltip content="왼쪽" position="left" show><Button variant="outline" color="assistive">Left</Button></Tooltip>
      <Tooltip content="오른쪽" position="right" show><Button variant="outline" color="assistive">Right</Button></Tooltip>
    </>
  );
}

import { Button, Icon, Tooltip } from "@jiran/ds-react";

export default function Example() {
  return (
    <>
      <Tooltip content="새로 고침"><Button variant="outline" color="assistive" iconOnly aria-label="새로 고침"><Icon name="refresh" /></Button></Tooltip>
      <Tooltip content="필터"><Button variant="outline" color="assistive" iconOnly aria-label="필터"><Icon name="filter" /></Button></Tooltip>
      <Tooltip content="삭제"><Button variant="outline" color="assistive" iconOnly aria-label="삭제"><Icon name="trash" /></Button></Tooltip>
    </>
  );
}

import { Button, Icon, Indicator, Tooltip } from "@jiran/ds-react";

export default function Example() {
  return (
    <>
      <Indicator tone="warn">검토 필요</Indicator>
      <Tooltip content="게시자 서명을 확인하지 못한 실행 파일입니다. 신뢰할 수 있는 파일이면 예외로 추가할 수 있습니다." multi show>
        <Button variant="text" color="assistive" size="sm" iconOnly aria-label="검토 필요 이유"><Icon name="info-circle" /></Button>
      </Tooltip>
    </>
  );
}

