/* JS Design System v0.9 · .spinner, .spinner-wrap, .skeleton, .skeleton-row, .progress, .progress-row · 토큰(var(--*))은 assets/style.css :root 참고 */
.tree-toggle .spinner{width:0.75rem;height:0.75rem;border-width:2px}
.spinner{display:inline-block;width:1.5rem;height:1.5rem;border:3px solid var(--line-neutral-secondary);border-top-color:var(--surface-brand-primary);border-radius:50%;animation:spin .8s linear infinite;line-height:1.6}
.spinner.sm{width:1rem;height:1rem;border-width:2px}
.spinner.lg{width:2.5rem;height:2.5rem;border-width:4px}
.spinner-wrap{display:inline-flex;flex-direction:column;align-items:center;gap:0.75rem;font-size:var(--font-size-12);color:var(--foreground-neutral-tertiary);line-height:max(1rem,16px);letter-spacing:0.0252em}
.skeleton{display:block;height:0.875rem;border-radius:var(--radius-md);background:linear-gradient(90deg,var(--surface-neutral-strong) 25%,var(--background-neutral-secondary) 50%,var(--surface-neutral-strong) 75%);background-size:200% 100%;animation:shimmer 1.4s infinite;line-height:1.6}
.skeleton.title{height:1.25rem;width:40%}
.skeleton.text{width:100%}
.skeleton.text.short{width:70%}
.skeleton.circle{width:2.5rem;height:2.5rem;border-radius:50%;flex:none}
.skeleton.rect{height:7.5rem;border-radius:var(--radius-md)}
.skeleton-row{display:flex;align-items:center;gap:0.75rem;width:100%;line-height:1.6}
.skeleton-row .lines{flex:1;display:flex;flex-direction:column;gap:0.5rem}
.spinner[data-delay]{animation:spin .8s linear infinite,ds-delay 0s var(--ds-delay,1s) both}
.skeleton[data-delay]{animation:shimmer 1.4s infinite,ds-delay 0s var(--ds-delay,1s) both}
.spinner-wrap[data-delay],.skeleton-row[data-delay]{animation:ds-delay 0s var(--ds-delay,1s) both}
.progress{width:100%;height:0.5rem;border-radius:var(--radius-full);background:var(--surface-neutral-strong);overflow:hidden;line-height:1.6}
.progress i{display:block;height:100%;background:var(--foreground-brand-primary);border-radius:var(--radius-full);transition:width var(--motion-base)}
.progress.sm{height:0.25rem}
.progress.success i{background:var(--foreground-positive-primary)}
.progress.danger i{background:var(--foreground-negative-primary)}
.progress-row{display:flex;flex-direction:column;gap:0.375rem;width:100%;font-size:var(--font-size-12);color:var(--foreground-neutral-secondary);line-height:max(1rem,16px);letter-spacing:0.0252em}
.progress-row .row{display:flex;justify-content:space-between}
.tbl .row-detail .spinner-wrap{flex-direction:row;font-size:var(--font-size-14);line-height:1.375rem;letter-spacing:0.0145em}
.progress-list .progress-row{gap:0.5rem}
.progress-list .progress-row .row b{font-weight:600;color:var(--foreground-neutral-primary)}
.progress-list .progress-row .row .target{color:var(--foreground-neutral-tertiary);margin-left:0.25rem}
.progress-list .progress{border-radius:0}
.progress-list .progress i{background:var(--chart-mono-1);border-radius:0}
.chart-state > .skeleton.rect{height:100%}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes ds-delay{from{visibility:hidden}to{visibility:visible}}
@keyframes shimmer{to{background-position:-200% 0}}

