import { Form, FormLegend, Stepper, TextField } from "@jiran/ds-react";

/* '다음'은 그 단계 폼을 검사한다 — 적용 그룹이 비어 있어 막힌다. 완료한 '기본 정보'는 눌러 돌아간다 */
export default function Example() {
  return (
    <Stepper
      defaultCurrent={1}
      steps={[
        { label: "기본 정보", content: <Form validate><FormLegend /><TextField id="sd-name" label="정책 이름" required help="2~40자" defaultValue="외부 USB 차단" /></Form> },
        { label: "적용 대상", content: <Form validate><FormLegend /><TextField id="sd-group" label="적용 그룹" required help="예: 영업팀" /></Form> },
        { label: "규칙 설정", content: <p className="t-body-2-reading">차단할 장치 종류와 예외를 정합니다.</p> },
        { label: "검토 · 배포", content: <p className="t-body-2-reading">설정을 확인한 뒤 완료를 누릅니다.</p> },
      ]}
    />
  );
}

import { Stepper } from "@jiran/ds-react";

const note = (t: string) => <p className="t-body-2-reading">{t}</p>;

export default function Example() {
  return (
    <Stepper
      layout="label-below"
      defaultCurrent={1}
      steps={[
        { label: "조직 정보", content: note("조직 이름과 관리자 연락처를 정합니다.") },
        { label: "보호 수준", content: note("기본 보호 수준을 고릅니다.") },
        { label: "에이전트 배포", content: note("설치 파일을 받아 단말에 설치합니다.") },
        { label: "알림 설정", content: note("위협을 알릴 채널을 고릅니다.") },
        { label: "검토", content: note("설정을 확인한 뒤 완료를 누릅니다.") },
      ]}
    />
  );
}

import { Form, FormLegend, Stepper, TextField } from "@jiran/ds-react";

/* 세로 — 현재 단계의 내용과 버튼이 그 단계 아래에 펼쳐진다 */
export default function Example() {
  return (
    <Stepper
      layout="vertical"
      defaultCurrent={1}
      steps={[
        { label: "기본 정보", content: <Form validate><FormLegend /><TextField id="sv-name" label="정책 이름" required help="2~40자" defaultValue="외부 USB 차단" /></Form> },
        { label: "적용 대상", content: <Form validate><FormLegend /><TextField id="sv-group" label="적용 그룹" required help="예: 영업팀" /></Form> },
        { label: "규칙 설정", content: <p className="t-body-2-reading">차단할 장치 종류와 예외를 정합니다.</p> },
        { label: "검토 · 배포", content: <p className="t-body-2-reading">설정을 확인한 뒤 완료를 누릅니다.</p> },
      ]}
    />
  );
}

import { Form, FormLegend, Stepper, TextField } from "@jiran/ds-react";

/* 자유 이동 — 어느 단계든 누른다. 떠날 때 폼이 통과하면 완료로 표시하고, '완료'는 막힌 첫 단계(적용 그룹)로 간다 */
export default function Example() {
  return (
    <Stepper
      nonLinear
      steps={[
        { label: "기본 정보", content: <Form validate><FormLegend /><TextField id="sn-name" label="정책 이름" required help="2~40자" defaultValue="외부 USB 차단" /></Form> },
        { label: "적용 대상", content: <Form validate><FormLegend /><TextField id="sn-group" label="적용 그룹" required help="예: 영업팀" /></Form> },
        { label: "규칙 설정", content: <p className="t-body-2-reading">차단할 장치 종류와 예외를 정합니다.</p> },
        { label: "검토 · 배포", content: <p className="t-body-2-reading">설정을 확인한 뒤 완료를 누릅니다.</p> },
      ]}
      onFinish={() => {}}
    />
  );
}

import { Steps } from "@jiran/ds-react";

/* 표시만 — 이동은 제품이 한다. 완료한 단계를 누르면 onStepClick */
export default function Example() {
  return <Steps aria-label="진행 단계" items={["기본 정보", "적용 대상", "규칙 설정", "검토 · 배포"]} current={2} onStepClick={() => {}} />;
}

