.code-view .title{min-width:0;font-size:var(--font-size-14);line-height:1.375rem;font-weight:500;color:var(--foreground-neutral-secondary);letter-spacing:0.0145em}
.code-view pre{contain:inline-size;margin:0;padding:0.75rem 1rem;border-radius:0;background:none;color:var(--foreground-neutral-primary);font-size:var(--font-size-12);line-height:max(1.25rem,20px);letter-spacing:0;tab-size:2;overflow:auto}
.code-view pre code{padding:0;border-radius:0;background:none;font-size:inherit}
.code-view pre:focus-visible{outline-offset:-1px}
.code-view.wrap pre{white-space:pre-wrap;overflow-wrap:anywhere}
.code-view .copy .ico,.copy-field .copy .ico{display:grid;place-items:center}
.code-view .copy .ico svg,.copy-field .copy .ico svg{width:1rem;height:1rem}
.code-view .copy .t,.copy-field .copy .t{display:inline-block;min-width:3em;text-align:left}
.code-view .copy.copy-done .ico,.copy-field .copy.copy-done .ico{color:var(--foreground-positive-primary)}
.code-view .copy.copy-failed .ico,.copy-field .copy.copy-failed .ico{color:var(--foreground-negative-strong)}
.terms .accordion summary .checkbox{font-weight:600}
.empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0.375rem;padding:3rem 1.5rem;text-align:center;width:100%;color:var(--foreground-neutral-tertiary);font-size:var(--font-size-14);background:var(--surface-elevated-primary);border:1px dashed var(--line-neutral-primary);border-radius:var(--radius-lg);line-height:1.375rem;letter-spacing:0.0145em}
.empty b{font-size:var(--font-size-16);color:var(--foreground-neutral-primary);line-height:1.625rem;letter-spacing:0.0057em}
.empty .ico{width:2.5rem;height:2.5rem;display:grid;place-items:center;font-size:var(--font-size-20);margin-bottom:0.375rem;color:var(--foreground-neutral-quaternary);line-height:1.75rem;letter-spacing:-0.012em}
.empty .ico svg{width:2.5rem;height:2.5rem;stroke-width:1.5}
.empty .btn{margin-top:0.625rem}
.empty.compact{padding:1.5rem;flex-direction:row;justify-content:flex-start;text-align:left;gap:0.75rem}
.empty.compact .ico{margin:0;width:2rem;height:2rem;font-size:var(--font-size-16);line-height:1.625rem;letter-spacing:0.0057em}
.empty.compact .ico svg{width:2rem;height:2rem}
.empty.compact b{font-size:var(--font-size-14);line-height:1.375rem;letter-spacing:0.0145em}
.empty.compact > div > span{display:block}
.empty.compact .btn{margin:0 0 0 auto}
.setting .ctrl .dropdown .trigger{min-width:11.25rem}
.status-item .indicator{font-weight:600}
.auth > .btn.solid{width:100%}
.auth > .link{align-self:center;font-size:var(--font-size-14);line-height:1.25rem;letter-spacing:0.0145em}
.log-row{font-size:var(--font-size-12);line-height:max(1rem,16px);letter-spacing:0.0252em}
.log-row td{white-space:nowrap}
.log-row:has(> td.truncate) > td:not(.truncate){width:1%}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes ds-delay{from{visibility:hidden}to{visibility:visible}}
