import { TimePicker } from "@jiran/ds-react";

export default function Example() {
  return <TimePicker label="백업 시각" defaultValue="02:00" help="매일 이 시각에 백업합니다." />;
}

import { TimePicker } from "@jiran/ds-react";

export default function Example() {
  return <TimePicker label="기준 시각" defaultValue="14:30:05" seconds />;
}

import { TimePicker } from "@jiran/ds-react";

