  const arrive = () => setItems((xs) => [{ id: `live-${xs.length}`, group: "오늘", severity: "critical", title: "관리자 계정 로그인이 5회 실패했습니다", sub: "admin · 203.0.113.24", time: "방금", datetime: new Date().toISOString(), unread: true }, ...xs]);
