import { useEffect, useRef, useState } from "react";
import { Button, ButtonGroup, Checkbox, Terms, TermsAll, TermsItem, TermsMessage } from "@jiran/ds-react";

const ITEMS = [
  { id: "tos", label: "서비스 이용약관", required: true },
  { id: "privacy", label: "개인정보 수집·이용", required: true },
  { id: "news", label: "보안 소식 이메일 수신", required: false },
];

export default function Example() {
  const [agreed, setAgreed] = useState<string[]>(["tos", "privacy"]);
  const [tried, setTried] = useState(false);
  const inputs = useRef<Record<string, HTMLInputElement | null>>({});
  const all = agreed.length === ITEMS.length, some = agreed.length > 0 && !all;
  const missing = ITEMS.filter((i) => i.required && !agreed.includes(i.id));
  useEffect(() => { if (!missing.length) setTried(false); }, [missing.length]);
  /* '다음' 은 늘 켜 둔다 — 누르면 막고, 남은 개수를 알린 뒤 첫 항목으로 포커스를 옮긴다 */
  const next = () => {
    if (missing.length) { setTried(true); inputs.current[missing[0].id]?.focus(); return; }
    // 다음 단계로
  };
  return (
    <Terms>
      <TermsAll>
        <Checkbox checked={all} indeterminate={some} aria-label="전체 동의" onChange={(on) => setAgreed(on ? ITEMS.map((i) => i.id) : [])}>전체 동의</Checkbox>
      </TermsAll>
      {ITEMS.map((it) => (
        <TermsItem key={it.id} required={it.required} onView={it.required ? () => {} : undefined}>
          <Checkbox ref={(el) => { inputs.current[it.id] = el; }} aria-invalid={tried && missing.includes(it) ? true : undefined} checked={agreed.includes(it.id)} onChange={(on) => setAgreed((s) => (on ? [...s, it.id] : s.filter((x) => x !== it.id)))}>{it.label}</Checkbox>
        </TermsItem>
      ))}
      <TermsMessage>{tried && missing.length ? `필수 약관 ${missing.length}개에 동의하지 않았습니다. 체크하고 다시 누르세요.` : null}</TermsMessage>
      <ButtonGroup end style={{ marginTop: 16 }}>
        <Button onClick={next}>다음</Button>
      </ButtonGroup>
    </Terms>
  );
}

import { Button, PopupActions, PopupSurface, PopupTitle } from "@jiran/ds-react";

/* 약관 전문 — 보기 버튼이 여는 팝업. 본문은 키보드로 스크롤되는 이름 있는 영역이다(문서 예제라 표면만 그린다) */
const DOCS = [
  {
    id: "terms-tos",
    title: "서비스 이용약관",
    body: [
      "제1조(목적) 이 약관은 지란지교시큐리티가 제공하는 보안 관리 서비스의 이용 조건과 절차를 정합니다.",
      "제2조(정의) 서비스란 회사가 제공하는 에이전트와 관리 콘솔을 말합니다. 이용자란 이 약관에 따라 서비스를 쓰는 조직과 그 구성원을 말합니다.",
      "제3조(약관의 효력) 이 약관은 서비스 화면에 게시하여 효력이 생깁니다. 회사는 관련 법령을 어기지 않는 범위에서 약관을 바꿀 수 있고, 바꾸면 적용일 7일 전에 알립니다.",
    ],
  },
  {
    id: "terms-privacy",
    title: "개인정보 수집·이용",
    body: [
      "수집 항목은 이름, 이메일, 소속 부서입니다. 관리자 계정을 만들고 보안 알림을 보내는 데 씁니다.",
      "보유 기간은 계정을 지운 뒤 30일입니다. 동의하지 않으면 관리자 계정을 만들 수 없습니다.",
    ],
  },
];

export default function Example() {
  const close = () => {};
  return (
    <>
      {DOCS.map((d) => (
        <PopupSurface key={d.id} id={d.id} onClose={close}>
          <PopupTitle>{d.title}</PopupTitle>
          <div className="popup-body terms-doc" tabIndex={0} role="region" aria-label={`${d.title} 전문`}>
            {d.body.map((p) => <p key={p}>{p}</p>)}
          </div>
          <PopupActions>
            <Button variant="outline" color="assistive" onClick={close}>닫기</Button>
          </PopupActions>
        </PopupSurface>
      ))}
    </>
  );
}

import { Accordion, Checkbox, Tag, Terms } from "@jiran/ds-react";

/* 약관이 짧으면 펼쳐 보이게 — 본문은 키보드로도 스크롤되게 이름 있는 영역으로 */
export default function Example() {
  return (
    <Terms>
      <Accordion
        defaultOpen
        style={{ maxWidth: 560 }}
        bodyStyle={{ maxHeight: 120, overflow: "auto" }}
        bodyProps={{ tabIndex: 0, role: "region", "aria-label": "서비스 이용약관 전문" }}
        title={<><Checkbox defaultChecked>서비스 이용약관</Checkbox><Tag tone="accent" size="sm">필수</Tag></>}
      >
        제1조(목적) 이 약관은 지란지교시큐리티가 제공하는 보안 관리 서비스의 이용 조건과 절차를 정합니다. 제2조(정의) 서비스란 회사가 제공하는 에이전트와 관리 콘솔을 말합니다. 제3조(약관의 효력) 이 약관은 서비스 화면에 게시하여 효력이 생깁니다. 회사는 약관을 바꾸면 적용일 7일 전에 알립니다.
      </Accordion>
    </Terms>
  );
}

