import { Button, PopupActions, PopupBody, PopupSurface, PopupTitle } from "@jiran/ds-react";

/* 단건 삭제 — 제목에 대상 이름, 본문에 사라지는 것과 영향. 취소가 먼저 */
export default function Example() {
  const close = () => {};
  return (
    <PopupSurface danger onClose={close}>
      <PopupTitle>'외부 USB 차단' 정책을 삭제할까요?</PopupTitle>
      <PopupBody>삭제한 정책은 복구할 수 없습니다. 이 정책이 적용된 에이전트 1,284대는 기본 정책으로 돌아갑니다.</PopupBody>
      <PopupActions>
        <Button variant="outline" color="assistive" onClick={close}>취소</Button>
        <Button color="negative">삭제</Button>
      </PopupActions>
    </PopupSurface>
  );
}

import { Button, PopupActions, PopupSurface, PopupTitle } from "@jiran/ds-react";

const NAMES = ["외부 USB 차단", "스크립트 실행 제한", "원격 접속 허용 목록"];
const TOTAL = 12;

/* 일괄 작업 — 개수와 이름 몇 개, 나머지는 외 n개. 본문에 목록이 있어 p 가 아닌 div 로 감싼다 */
export default function Example() {
  const close = () => {};
  return (
    <PopupSurface danger onClose={close} aria-describedby="dc2-b">
      <PopupTitle>정책 {TOTAL}개를 삭제할까요?</PopupTitle>
      <div className="popup-body" id="dc2-b">
        <p>삭제한 정책은 복구할 수 없습니다. 적용된 에이전트는 기본 정책으로 돌아갑니다.</p>
        <ul className="danger-list">
          {NAMES.map((n) => <li key={n}>{n}</li>)}
          <li>외 {TOTAL - NAMES.length}개</li>
        </ul>
      </div>
      <PopupActions>
        <Button variant="outline" color="assistive" onClick={close}>취소</Button>
        <Button color="negative">삭제</Button>
      </PopupActions>
    </PopupSurface>
  );
}

import { Button, Form, PopupActions, PopupBody, PopupSurface, PopupTitle, TextField } from "@jiran/ds-react";

const NAME = "SIEM 연동";

/* 이름 입력 확인 — 삭제 버튼은 늘 켜 두고, 누르면 검사한다. 이름이 다르면 막고 입력칸 아래에 고치는 법을 적는다 */
export default function Example() {
  const close = () => {};
  return (
    <PopupSurface danger onClose={close}>
      <PopupTitle>'{NAME}'을 삭제할까요?</PopupTitle>
      <PopupBody>연동을 지우면 이벤트 전송이 바로 멈추고, 이 연동을 쓰는 보고서 3개가 비게 됩니다. 복구할 수 없습니다.</PopupBody>
      <Form bare validate className="popup-form" id="dc3-form" onSubmit={(e) => { e.preventDefault(); /* 삭제 실행 */ }}>
        <TextField
          id="dc3-name"
          label={`확인을 위해 ${NAME} 을 입력하세요`}
          required
          requiredMark={false}
          pattern={NAME}
          autoComplete="off"
          help="이름이 같아야 삭제됩니다."
          messages={{ required: "연동 이름을 입력하세요.", pattern: `연동 이름이 다릅니다. ${NAME} 을 그대로 입력하세요.` }}
        />
      </Form>
      <PopupActions>
        <Button variant="outline" color="assistive" onClick={close}>취소</Button>
        <Button type="submit" form="dc3-form" color="negative">삭제</Button>
      </PopupActions>
    </PopupSurface>
  );
}

import { Toast, ToastStack } from "@jiran/ds-react";

/* 되돌리기 — 되돌릴 수 있는 동작은 묻지 않고 실행한 뒤 실행 취소가 있는 Toast. 앱에서는 useToast 가 10초 동안 띄운다 */
export default function Example() {
  return (
    <ToastStack>
      <Toast action={{ label: "실행 취소", onClick: () => {} }}>정책 3개를 보관함으로 옮겼습니다</Toast>
    </ToastStack>
  );
}

