import { useState } from "react";
import { Button, ButtonGroup, Field, FileUpload, Icon, Notice, Stack, Table, TableBody, TableCell, TableHead, TableHeader, TableRow, Tag, type UploadItem } from "@jiran/ds-react";

const MB = 1024 * 1024;
const ERRORS = [
  { line: "18", name: "PC-2041", ip: "10.0.4.256", kind: "IP 형식", fix: "0~255 사이 숫자로 고치세요" },
  { line: "342", name: "PC-0932", ip: "10.0.7.10", kind: "중복", fix: "18줄과 같은 IP 입니다" },
  { line: "1,107", name: "(비어 있음)", ip: "10.0.9.44", kind: "필수", fix: "단말 이름을 채우세요" },
];

/* 가져오기 — 올리면 줄마다 검사하고 오류 줄만 표로. 올바른 줄만 가져오고, 오류 줄은 내려받아 고친다 */
export default function Example() {
  const [files, setFiles] = useState<UploadItem[]>([{ id: "imp1", name: "agents-2026-11.csv", size: 212 * 1024, status: "done" }]);
  return (
    <Stack>
      <Field label="단말 목록 파일" help="CSV, 5MB 이하. 첫 줄은 단말 이름, IP, 그룹 열입니다.">
        <FileUpload accept=".csv" maxSize={5 * MB} items={files}
          onAdd={(added) => setFiles(added.slice(0, 1).map(({ id, file }) => ({ id, name: file.name, size: file.size, status: "uploading", progress: 0 })))}
          onRemove={(id) => setFiles((p) => p.filter((x) => x.id !== id))}
        />
      </Field>
      <Notice tone="warning" title="1,284줄 중 3줄을 가져올 수 없습니다"
        actions={<Button variant="outline" color="assistive" size="sm"><Icon name="download" />오류 줄 내려받기</Button>}>
        오류 줄을 고쳐 다시 올리거나, 올바른 1,281줄만 가져오세요.
      </Notice>
      <Table density="compact">
        <TableHead>
          <TableRow><TableHeader className="num">줄</TableHeader><TableHeader>단말 이름</TableHeader><TableHeader>IP</TableHeader><TableHeader>오류</TableHeader></TableRow>
        </TableHead>
        <TableBody>
          {ERRORS.map((r) => (
            <TableRow key={r.line}>
              <TableCell className="num">{r.line}</TableCell>
              <TableCell>{r.name}</TableCell>
              <TableCell>{r.ip}</TableCell>
              <TableCell><Tag tone="high" size="sm">{r.kind}</Tag> {r.fix}</TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
      <ButtonGroup end>
        <Button variant="outline" color="assistive">취소</Button>
        <Button>1,281줄 가져오기</Button>
      </ButtonGroup>
    </Stack>
  );
}

import { Button, Checkbox, DateRangePicker, PopupActions, PopupForm, PopupSurface, PopupTitle, Radio, RadioGroup, TimePicker } from "@jiran/ds-react";

const day = (n: number) => { const d = new Date(); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() - n); return d; };
const PRESETS = [7, 30].map((n) => ({ label: `최근 ${n}일`, range: (): [Date, Date] => [day(n - 1), day(0)] }));

/* 내보내기 — 형식과 기간을 고른다. 개인정보 열은 기본으로 빼고, 긴 기간은 예약 시각에 보낸다 */
export default function Example() {
  const close = () => {};
  return (
    <PopupSurface onClose={close}>
      <PopupTitle>로그 내보내기</PopupTitle>
      <PopupForm>
        <RadioGroup legend="형식" name="exp-fmt" defaultValue="csv">
          <Radio value="csv">CSV</Radio>
          <Radio value="json">JSON</Radio>
        </RadioGroup>
        <DateRangePicker id="exp-range" label="기간" max={day(0)} presets={PRESETS} defaultValue={{ start: new Date(2026, 10, 8), end: new Date(2026, 10, 14) }} />
        <Checkbox description="개인정보가 들어갑니다. 내보낸 기록은 감사 로그에 남습니다">사용자 이름과 이메일 포함</Checkbox>
        <TimePicker id="exp-time" label="예약 시각" defaultValue="02:00" help="30일이 넘는 기간은 이 시각에 보냅니다." />
      </PopupForm>
      <PopupActions>
        <Button variant="outline" color="assistive" onClick={close}>취소</Button>
        <Button>내보내기</Button>
      </PopupActions>
    </PopupSurface>
  );
}

