.tag.outline.high{box-shadow:inset 0 0 0 1px var(--line-cautionary-primary)}
.tag.outline.medium{box-shadow:inset 0 0 0 1px var(--line-accent-light-blue)}
.tag.outline.low{box-shadow:inset 0 0 0 1px var(--line-accent-lime)}
.tag.outline.pending{box-shadow:inset 0 0 0 1px var(--line-accent-cyan)}
.tag.outline.ok{box-shadow:inset 0 0 0 1px var(--line-positive-primary)}
.tag.outline.accent{box-shadow:inset 0 0 0 1px var(--line-brand-primary)}
