/* JS Design System v0.9 · .steps, .stepper, .step-panel, .step-actions, .sr-only, .card, .card-grid, .form, .form-legend, .field, .code-inputs, .radio, .radio-group, .code-view, .code-inline, .copy-field, .indicator, .count, .with-count, .btn, .btn-group, .onboard, .keep-all, .t-body-1-normal, .t-semibold · 토큰(var(--*))은 assets/style.css :root 참고 */
.t-body-1-normal{font-size:var(--font-size-16);line-height:1.5rem;font-weight:400;letter-spacing:0.0057em}
