import { useState } from "react";
import { Button, Chip, ChipGroup, Combobox, DataTable, DateRangePicker, Icon, Indicator, Pagination, PaginationBar, SearchBar, Spacer, Stack, Tag, Toolbar, type DataTableColumn } from "@jiran/ds-react";

type Row = { id: string; time: string; sev: "critical" | "high"; event: string; target: string; status: "blocked" | "review" };
const ROWS: Row[] = [
  { id: "1", time: "09:41:12", sev: "critical", event: "랜섬웨어 행위 탐지", target: "PC-2041 · 김민준", status: "blocked" },
  { id: "2", time: "09:36:47", sev: "high", event: "알려진 악성코드 차단", target: "PC-2041 · 김민준", status: "blocked" },
  { id: "3", time: "09:12:03", sev: "high", event: "의심 스크립트 실행", target: "PC-2041 · 김민준", status: "review" },
];
const COLUMNS: DataTableColumn<Row>[] = [
  { key: "time", header: "시간", sortable: true },
  { key: "sev", header: "심각도", render: (r) => <Tag tone={r.sev}>{r.sev === "critical" ? "Critical" : "High"}</Tag> },
  { key: "event", header: "이벤트", render: (r) => <a href="#" className="link">{r.event}</a> },
  { key: "target", header: "대상" },
  { key: "status", header: "상태", render: (r) => (r.status === "blocked" ? <Indicator tone="danger">차단</Indicator> : <Indicator tone="warn">검토 필요</Indicator>) },
];
const SEVS = ["Critical", "High", "Medium", "Low", "Info"].map((label) => ({ value: label, label }));

const today = new Date();
const daysAgo = (n: number) => new Date(today.getFullYear(), today.getMonth(), today.getDate() - n);
const PRESETS = [{ label: "최근 7일", range: (): [Date, Date] => [daysAgo(6), today] }, { label: "최근 30일", range: (): [Date, Date] => [daysAgo(29), today] }];

/* 툴바 한 줄 = 검색 · 심각도(여러 개) · 기간 — 검색칸이 남는 폭을 맞춘다(2026-11-16). 대시보드에서 넘어온 조건은 결과 줄의 입력값 Chip — 하나씩 지운다 */
export default function Example() {
  const [sev, setSev] = useState<string[]>(["Critical"]);
  const [conds, setConds] = useState(["대상: PC-2041", "정책: 랜섬웨어 행위 차단"]);
  const [page, setPage] = useState(1);
  return (
    <Stack>
      <Toolbar>
        <SearchBar placeholder="이벤트, 단말, IP 검색" label="이벤트 검색" />
        <Combobox multiple options={SEVS} value={sev} onChange={(v) => setSev(v as string[])} placeholder="심각도" label="심각도" />
        <DateRangePicker aria-label="조회 기간" max={today} presets={PRESETS} defaultValue={{ start: daysAgo(6), end: today }} />
      </Toolbar>
      <Toolbar className="sub">
        <span>결과 <b>128</b>건</span>
        <ChipGroup>
          {conds.map((c) => (
            <Chip key={c} size="sm" onRemove={() => setConds((s) => s.filter((x) => x !== c))}>{c}</Chip>
          ))}
        </ChipGroup>
        <Button variant="text" color="assistive" size="sm" onClick={() => { setConds([]); setSev([]); }}>필터 초기화</Button>
        <Spacer />
        <Button variant="outline" color="assistive" size="sm" iconLeft={<Icon name="download" />}>내보내기</Button>
      </Toolbar>
      <DataTable hover nowrap columns={COLUMNS} rows={ROWS} rowKey={(r) => r.id} defaultSort={{ key: "time", dir: "desc" }} />
      <PaginationBar summary={<>총 <b>128</b>건 · 1–50</>}>
        <Pagination compact page={page} total={3} onChange={setPage} />
      </PaginationBar>
    </Stack>
  );
}

import { Button, Empty, SearchBar, Stack, Toolbar } from "@jiran/ds-react";

/* 결과가 없으면 표 대신 Empty State — 무엇을 바꾸면 되는지와 필터 초기화 */
export default function Example() {
  return (
    <Stack>
      <Toolbar>
        <SearchBar defaultValue="랜섬웨어 2025" placeholder="이벤트, 단말, IP 검색" label="이벤트 검색 결과 없음 예시" />
      </Toolbar>
      <Toolbar className="sub"><span>결과 <b>0</b>건</span></Toolbar>
      <Empty icon="search" title="'랜섬웨어 2025' 에 대한 결과가 없습니다" actions={<Button variant="outline" color="assistive">필터 초기화</Button>}>
        검색어를 줄이거나 기간을 최근 30일로 넓혀 보세요.
      </Empty>
    </Stack>
  );
}

patterns.css:
/* JS Design System v0.9 · .indicator, .count, .with-count, .notice, .toast, .toast-stack, .banner, .card, .card-grid, .kpi, .kpi-grid, .kpi-foot, .delta, .delta-note, .chart, .progress-list, .chart-card, .chart-head, .chart-sub, .chart-action, .chart-figure, .chart-view, .chart-tools, .chart-table, .chart-canvas, .chart-state, .donut, .donut-row, .chart-legend, .sparkline, .btn, .btn-group, .status-list, .status-item, .stack, .row-2, .progress-row, .progress, .keep-all · 토큰(var(--*))은 assets/style.css :root 참고 */
.keep-all{word-break:keep-all;overflow-wrap:anywhere}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:0.375rem;height:2.5rem;padding:0 1.25rem;border-radius:var(--radius-md);border:1px solid transparent;background:transparent;font:inherit;font-size:var(--font-size-14);font-weight:600;line-height:1.25rem;cursor:pointer;white-space:nowrap;text-decoration:none;transition:background var(--motion-fast),border-color var(--motion-fast);letter-spacing:0.0145em}
.btn.sm{height:2rem;padding:0 0.875rem;font-size:var(--font-size-12);border-radius:var(--radius-sm);line-height:max(1rem,16px);letter-spacing:0.0252em}
.btn.md{height:2.5rem;padding:0 1.25rem;font-size:var(--font-size-14);line-height:1.25rem;letter-spacing:0.0145em}
.btn.lg{height:3rem;padding:0 1.625rem;font-size:var(--font-size-16);line-height:1.5rem;letter-spacing:0.0057em}
.btn:where(.solid.primary){background:var(--surface-brand-primary);background-image:var(--surface-brand-gradient);color:var(--brand-label)}
.btn:where(.solid.primary):where(:not(.loading,[disabled],[aria-disabled="true"])):hover{background:var(--surface-brand-strong);background-image:var(--surface-brand-gradient-strong)}
.btn:where(.solid.primary):where(:not(.loading,[disabled],[aria-disabled="true"])):active{background:var(--surface-brand-heavy);background-image:var(--surface-brand-gradient-heavy)}
.btn:where(.outline.primary){border-color:var(--line-brand-strong);color:var(--foreground-brand-primary)}
.btn:where(.outline.primary):where(:not(.loading,[disabled],[aria-disabled="true"])):hover{background:var(--surface-brand-subtle)}
.btn:where(.outline.primary):where(:not(.loading,[disabled],[aria-disabled="true"])):active{background:var(--surface-brand-subtle-strong)}
.btn:where(.solid.assistive){background:var(--surface-neutral-tertiary);color:var(--foreground-neutral-primary)}
.btn:where(.solid.assistive):where(:not(.loading,[disabled],[aria-disabled="true"])):hover{background:var(--surface-neutral-secondary)}
.btn:where(.solid.assistive):where(:not(.loading,[disabled],[aria-disabled="true"])):active{background:var(--surface-neutral-strong)}
.btn:where(.outline.assistive){border-color:var(--line-neutral-primary);color:var(--foreground-neutral-primary)}
.btn:where(.outline.assistive):where(:not(.loading,[disabled],[aria-disabled="true"])):hover{background:var(--surface-neutral-secondary)}
.btn:where(.outline.assistive):where(:not(.loading,[disabled],[aria-disabled="true"])):active{background:var(--surface-neutral-strong)}
.btn:where(.solid.negative){background:var(--surface-negative-primary);color:var(--foreground-negative-strong)}
.btn:where(.solid.negative):where(:not(.loading,[disabled],[aria-disabled="true"])):hover{background:var(--surface-negative-strong)}
.btn:where(.solid.negative):where(:not(.loading,[disabled],[aria-disabled="true"])):active{background:var(--surface-negative-heavy)}
.btn:where(.outline.negative){border-color:var(--line-negative-primary);color:var(--foreground-negative-strong)}
.btn:where(.outline.negative):where(:not(.loading,[disabled],[aria-disabled="true"])):hover{background:var(--surface-negative-hover)}
.btn:where(.outline.negative):where(:not(.loading,[disabled],[aria-disabled="true"])):active{background:var(--surface-negative-pressed);border-color:var(--line-negative-strong)}
.btn:where(.text){color:var(--foreground-brand-primary)}
.btn.text{padding-left:0.5rem;padding-right:0.5rem}
.btn:where(.text):where(:not(.loading,[disabled],[aria-disabled="true"])):hover{background:var(--surface-brand-subtle)}
.btn:where(.text):where(:not(.loading,[disabled],[aria-disabled="true"])):active{background:var(--surface-brand-subtle-strong)}
.btn:where(.text.assistive){color:var(--foreground-neutral-secondary)}
.btn:where(.text.assistive):where(:not(.loading,[disabled],[aria-disabled="true"])):hover{background:var(--surface-neutral-secondary);color:var(--foreground-neutral-primary)}
.btn:where(.text.assistive):where(:not(.loading,[disabled],[aria-disabled="true"])):active{background:var(--surface-neutral-strong);color:var(--foreground-neutral-primary)}
.btn.icon-only{width:2.5rem;padding:0}
.btn.icon-only.sm{width:2rem}
.btn.icon-only.lg{width:3rem}
.btn:where(.icon-only:not(.solid,.outline).primary){color:var(--foreground-brand-primary)}
.btn:where(.icon-only:not(.solid,.outline).primary):where(:not(.loading,[disabled],[aria-disabled="true"])):hover{background:var(--surface-brand-subtle)}
.btn:where(.icon-only:not(.solid,.outline).primary):where(:not(.loading,[disabled],[aria-disabled="true"])):active{background:var(--surface-brand-subtle-strong)}
.btn:where(.icon-only:not(.solid,.outline).assistive){color:var(--foreground-neutral-secondary)}
.btn:where(.icon-only:not(.solid,.outline).assistive):where(:not(.loading,[disabled],[aria-disabled="true"])):hover{background:var(--surface-neutral-secondary);color:var(--foreground-neutral-primary)}
.btn:where(.icon-only:not(.solid,.outline).assistive):where(:not(.loading,[disabled],[aria-disabled="true"])):active{background:var(--surface-neutral-strong);color:var(--foreground-neutral-primary)}
.btn:where(.icon-only:not(.solid,.outline).negative){color:var(--foreground-negative-strong)}
.btn:where(.icon-only:not(.solid,.outline).negative):where(:not(.loading,[disabled],[aria-disabled="true"])):hover{background:var(--surface-negative-hover)}
.btn:where(.icon-only:not(.solid,.outline).negative):where(:not(.loading,[disabled],[aria-disabled="true"])):active{background:var(--surface-negative-pressed)}
.btn svg{width:1.125rem;height:1.125rem;flex:none}
.btn.sm svg{width:1rem;height:1rem}
.btn.lg svg{width:1.25rem;height:1.25rem}
.btn.block{width:100%}
.btn[disabled],.btn[aria-disabled="true"]{background:var(--surface-disable-primary);border-color:transparent;color:var(--foreground-disable-primary);cursor:not-allowed}
.btn:where(.outline)[disabled],.btn:where(.outline)[aria-disabled="true"]{background:transparent;border-color:var(--surface-disable-primary)}
.btn:where(.text,.icon-only:not(.solid,.outline))[disabled],.btn:where(.text,.icon-only:not(.solid,.outline))[aria-disabled="true"]{background:transparent}
.btn.loading{position:relative;color:transparent;cursor:progress}
.btn.loading::after{content:"";position:absolute;box-sizing:border-box;width:1.125rem;height:1.125rem;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;color:var(--brand-label);animation:spin .8s linear infinite}
.btn.sm.loading::after{width:1rem;height:1rem}
.btn.lg.loading::after{width:1.25rem;height:1.25rem}
.btn:where(.assistive).loading::after{color:var(--foreground-brand-primary)}
.btn:where(.outline.primary,.text:not(.assistive),.icon-only:not(.solid,.outline).primary).loading::after{color:var(--foreground-brand-primary)}
.btn:where(.negative:not(.text)).loading::after{color:var(--foreground-negative-strong)}
.btn-group{display:inline-flex;flex-wrap:wrap;gap:0.75rem;align-items:center;line-height:1.6}
.btn-group.end{justify-content:flex-end;width:100%}
.btn-group.vertical{flex-direction:column;align-items:stretch;gap:0.5rem}
.notify-panel[hidden],.notify .count[hidden]{display:none}
.calendar .cal-foot .btn.text+.btn:not(.text){margin-left:auto}
.menu-state .btn{margin-left:auto;flex:none}
.tabs .tab .count{font-size:var(--font-size-12);font-weight:700;padding:1px 0.375rem;border-radius:var(--radius-full);background:var(--surface-neutral-strong);color:var(--foreground-neutral-secondary);min-width:0;height:auto;line-height:max(1rem,16px);letter-spacing:0.0252em}
.tabs .tab.on .count{background:var(--surface-brand-subtle);color:var(--foreground-brand-primary)}
.sidenav a .count{margin-left:auto}
.sidenav.collapsed a span,.sidenav.collapsed .group,.sidenav.collapsed a .count,.sidenav.collapsed a.sub,.sidenav.collapsed .foot{display:none}
.card .avatar-group,.side-panel .avatar-group,.popup .avatar-group{--avatar-ring:var(--surface-elevated-primary)}
.avatar-group > .btn.avatar-group-more{margin-left:0.25rem}
.card{background:var(--surface-elevated-primary);border-radius:var(--radius-lg);border:1px solid var(--line-neutral-secondary);padding:var(--card-pad);display:flex;flex-direction:column;gap:0.75rem;min-width:16.25rem;position:relative;line-height:1.6}
.card .card-head{display:flex;align-items:center;justify-content:space-between;gap:0.75rem}
.card .title{font-size:var(--font-size-16);line-height:1.5rem;font-weight:600;margin:0;letter-spacing:0.0057em}
.card .desc{font-size:var(--font-size-14);color:var(--foreground-neutral-secondary);margin:0;line-height:1.375rem;letter-spacing:0.0145em}
.card .card-foot{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:0.75rem;margin-top:auto;padding-top:0.25rem}
.card .card-meta{display:grid;grid-template-columns:max-content 1fr;gap:0.375rem 1rem;margin:0;font-size:var(--font-size-14);line-height:1.375rem;letter-spacing:0.0145em}
.card .card-meta dt{color:var(--foreground-neutral-secondary)}
.card .card-meta dd{margin:0;min-width:0;color:var(--foreground-neutral-primary);overflow-wrap:anywhere}
.card.md{padding:var(--card-pad);gap:0.75rem}
.card.sm,.card.compact{padding:1rem;gap:0.5rem}
.card.sm .title,.card.compact .title{font-size:var(--font-size-14);line-height:1.25rem;letter-spacing:0.0145em}
.card.clickable{appearance:none;font:inherit;letter-spacing:inherit;color:inherit;text-align:left;text-decoration:none;cursor:pointer;transition:box-shadow var(--motion-fast)}
.card.clickable>svg{flex:none;color:var(--foreground-neutral-secondary)}
.card.bordered{box-shadow:none;border:1px solid var(--line-neutral-secondary)}
.card.clickable:not(:disabled,[aria-disabled="true"]):hover{box-shadow:var(--shadow-2)}
.card.on{box-shadow:inset 0 0 0 2px var(--surface-brand-primary);background:var(--surface-brand-subtle)}
.card.on>svg{color:var(--foreground-brand-primary)}
.card.clickable.on:not(:disabled,[aria-disabled="true"]):hover{box-shadow:inset 0 0 0 2px var(--surface-brand-primary),var(--shadow-2)}
.card.bordered.on{box-shadow:inset 0 0 0 2px var(--surface-brand-primary)}
.card.flat{border-color:transparent}
.card.clickable:is(:disabled,[aria-disabled="true"]){cursor:not-allowed;background:var(--surface-disable-primary);box-shadow:none}
.card.clickable:is(:disabled,[aria-disabled="true"]) .title,.card.clickable:is(:disabled,[aria-disabled="true"])>svg{color:var(--foreground-disable-primary)}
.card.clickable:is(:disabled,[aria-disabled="true"]) .desc{color:var(--foreground-neutral-tertiary)}
.card .empty{border:0;background:none;padding:1.5rem 0}
.card .empty b{font-size:var(--font-size-14);line-height:1.375rem;letter-spacing:0.0145em}
.card .empty .ico{width:2.25rem;height:2.25rem}
.card .empty .ico svg{width:2.25rem;height:2.25rem}
.card .empty.error .ico{color:var(--foreground-negative-strong)}
.card.flush{padding:0;gap:0;overflow:hidden}
.card.flush .card-head{padding:1rem var(--card-pad)}
.card.flush:is(.sm,.compact) .card-head{padding:0.75rem 1rem}
.card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(16.25rem,1fr));gap:var(--card-gap);width:100%;line-height:1.6}
.notice{display:flex;gap:0.75rem;align-items:flex-start;border-radius:var(--radius-lg);padding:1.25rem 1.125rem;font-size:var(--font-size-14);width:100%;background:var(--background-neutral-secondary);line-height:1.375rem;letter-spacing:0.0145em}
.notice b{display:block;margin-bottom:2px}
.notice .ico{flex:none;width:1.25rem;height:1.25rem;display:grid;place-items:center;color:var(--foreground-neutral-secondary);margin-top:1px}
.notice .ico svg{width:1.25rem;height:1.25rem}
.notice .close{margin-left:auto;flex:none;border:0;background:transparent;color:var(--foreground-neutral-tertiary);font:inherit;line-height:1;cursor:pointer;padding:2px;display:grid;place-items:center}
.notice .close svg{width:0.875rem;height:0.875rem}
.notice .close:hover{color:var(--foreground-neutral-primary)}
.notice .actions{display:flex;gap:0.5rem;margin-top:0.5rem}
.notice ul{margin:0.25rem 0 0;padding-left:1.2em;max-width:none}
.notice li + li{margin-top:0.25rem}
.notice.info{background:var(--surface-accent-cyan)}
.notice.info .ico{color:var(--foreground-accent-cyan)}
.notice.success{background:var(--surface-positive-primary)}
.notice.success .ico{color:var(--foreground-positive-primary)}
.notice.warning{background:var(--surface-cautionary-primary)}
.notice.warning .ico{color:var(--foreground-cautionary-primary)}
.notice.danger{background:var(--surface-negative-primary)}
.notice.danger .ico{color:var(--foreground-negative-primary)}
.toast{display:inline-flex;align-items:center;gap:0.75rem;width:22.5rem;max-width:100%;padding:0.75rem 1rem;border-radius:var(--radius-lg);background:var(--surface-neutral-inverse);color:var(--foreground-neutral-inverse);font-size:var(--font-size-14);box-shadow:var(--shadow-3);line-height:1.375rem;letter-spacing:0.0145em}
.toast .ico{flex:none;width:1.25rem;height:1.25rem;display:grid;place-items:center;color:var(--foreground-positive-primary)}
.toast .ico svg{width:1.25rem;height:1.25rem}
.toast.danger .ico{color:var(--foreground-negative-primary)}
.toast .action{margin-left:auto;background:none;border:0;color:var(--foreground-brand-inverse);font:inherit;font-size:var(--font-size-12);font-weight:600;cursor:pointer;white-space:nowrap;line-height:max(1rem,16px);letter-spacing:0.0252em}
.toast .action:hover{text-decoration:underline}
.toast .close,.banner .close{flex:none;margin-left:auto;border:0;background:transparent;color:inherit;font:inherit;line-height:1;cursor:pointer;padding:2px;display:grid;place-items:center;border-radius:var(--radius-sm)}
.toast .close svg,.banner .close svg{width:0.875rem;height:0.875rem}
.toast .action~.close,.banner .btn~.close{margin-left:0}
.toast button:focus-visible,.banner .close:focus-visible{outline-color:currentColor}
.toast-stack{display:flex;flex-direction:column;gap:0.5rem;align-items:flex-end;max-width:100%;line-height:1.6}
.toast-stack.fixed{position:fixed;right:1.5rem;bottom:1.5rem;z-index:110;max-width:calc(100vw - 3rem)}
.banner{display:flex;align-items:center;gap:0.75rem;width:100%;padding:0.625rem 1.25rem;background:var(--surface-brand-primary);background-image:var(--surface-brand-gradient);color:var(--brand-label);font-size:var(--font-size-14);font-weight:500;line-height:1.375rem;letter-spacing:0.0145em}
.banner .btn{margin-left:auto}
.banner.warning{background:var(--surface-cautionary-primary);color:var(--foreground-neutral-primary)}
.banner.danger{background:var(--surface-negative-strong);color:var(--foreground-neutral-primary)}
.banner:not(.warning):not(.danger) .btn:where(.outline.assistive:not([disabled],[aria-disabled="true"])){border-color:var(--brand-label)}
.banner:not(.warning):not(.danger) .btn:where(.outline.assistive:not(.loading,[disabled],[aria-disabled="true"])){color:var(--brand-label)}
.banner:not(.warning):not(.danger) .btn:where(.outline.assistive:not(.loading,[disabled],[aria-disabled="true"])):hover{background:var(--surface-brand-strong)}
.banner:not(.warning):not(.danger) .btn:where(.outline.assistive:not(.loading,[disabled],[aria-disabled="true"])):active{background:var(--surface-brand-heavy)}
.banner:not(.warning):not(.danger) .btn:where(.outline.assistive).loading::after{color:var(--brand-label)}
.banner .btn:focus-visible{outline-color:currentColor}
.banner .btn:is(.loading,[aria-disabled="true"]):focus-visible{outline-color:var(--foreground-neutral-primary)}
.banner:not(.warning):not(.danger) .btn:is(.loading,[aria-disabled="true"]):focus-visible{outline-color:var(--brand-label)}
.progress{width:100%;height:0.5rem;border-radius:var(--radius-full);background:var(--surface-neutral-strong);overflow:hidden;line-height:1.6}
.progress i{display:block;height:100%;background:var(--foreground-brand-primary);border-radius:var(--radius-full);transition:width var(--motion-base)}
.progress.sm{height:0.25rem}
.progress.success i{background:var(--foreground-positive-primary)}
.progress.danger i{background:var(--foreground-negative-primary)}
.progress-row{display:flex;flex-direction:column;gap:0.375rem;width:100%;font-size:var(--font-size-12);color:var(--foreground-neutral-secondary);line-height:max(1rem,16px);letter-spacing:0.0252em}
.progress-row .row{display:flex;justify-content:space-between}
