examples.react:
import { Button, Checkbox, Form, Link, Notice, TextField } from "@jiran/ds-react";

/* 로그인 실패는 폼 맨 위 Notice 한 곳에 — 어느 칸이 틀렸는지는 알리지 않고 남은 횟수와 잠금 시간을 함께 적는다 */
export default function Example() {
  return (
    <Form validate className="auth">
      <h2 className="auth-title t-title-3">관리 콘솔 로그인</h2>
      <Notice tone="danger" role="alert" title="아이디 또는 비밀번호가 맞지 않습니다">5번 틀리면 10분 동안 로그인할 수 없습니다. 남은 횟수는 3번입니다.</Notice>
      <TextField id="si-id" label="아이디" defaultValue="admin@jiran.com" autoComplete="username" required requiredMark={false} />
      <TextField id="si-pw" label="비밀번호" type="password" reveal autoComplete="current-password" required requiredMark={false} />
      <div className="auth-row">
        <Checkbox defaultChecked>아이디 저장</Checkbox>
        <Link href="#" standalone>비밀번호 찾기</Link>
      </div>
      <Button type="submit" size="lg">로그인</Button>
    </Form>
  );
}

import { Button, Checkbox, CodeInput, Form, Link } from "@jiran/ds-react";

/* 2단계 인증 코드는 큰 칸 여섯 — 한 자리씩 치면 다음 칸으로 가고, 붙여넣기와 문자 자동 채우기(one-time-code)는 모든 칸을 한 번에 채운다 */
export default function Example() {
  return (
    <Form validate className="auth">
      <h2 className="auth-title t-title-3">2단계 인증</h2>
      <p className="auth-desc">인증 앱에 표시된 6자리 숫자를 입력하세요.</p>
      <CodeInput id="si-otp" label="인증 코드" name="otp" required requiredMark={false} help="코드는 30초마다 바뀝니다." messages={{ required: "인증 코드를 입력하세요.", code: "숫자 6자리를 모두 입력하세요." }} />
      <Checkbox>이 기기에서 30일 동안 묻지 않기</Checkbox>
      <Button type="submit" size="lg">확인</Button>
      <Link href="#" standalone>다른 방법으로 인증</Link>
    </Form>
  );
}

import { Button, PopupActions, PopupSurface, PopupTitle } from "@jiran/ds-react";

/* 세션 만료 전 확인 — 남은 시간을 보이고 연장이 주 버튼. 닫기 · Esc 도 연장으로 본다 */
/* 본문이 두 문단이라 PopupBody(p) 대신 div.popup-body — 위험 확인이 아니어서 aria-describedby 를 잇지 않는다 */
export default function Example() {
  return (
    <PopupSurface onClose={() => {}}>
      <PopupTitle>로그인을 연장할까요?</PopupTitle>
      <div className="popup-body">
        <p>오래 쓰지 않아 곧 자동으로 로그아웃됩니다. 저장하지 않은 입력은 사라집니다.</p>
        <p className="auth-timer" role="timer">남은 시간 <b>01:58</b></p>
      </div>
      <PopupActions>
        <Button variant="outline" color="assistive">로그아웃</Button>
        <Button>연장</Button>
      </PopupActions>
    </PopupSurface>
  );
}

