import { Button, DatePicker, Form, FormLegend, PopupActions, PopupSurface, PopupTitle, Radio, RadioGroup, TextField } from "@jiran/ds-react";

/* 만료가 없는 키는 만들 수 없게 기본값을 둔다 — 최대 1년. 범위는 읽기 전용을 미리 골라 둔다 */
export default function Example() {
  return (
    <PopupSurface onClose={() => {}}>
      <PopupTitle>API 키 만들기</PopupTitle>
      <Form id="sec-create-form" className="popup-body" validate onSubmit={(e) => e.preventDefault()}>
        <FormLegend />
        <TextField id="sec-name" label="키 이름" required placeholder="연동할 서비스 이름" help="목록에서 알아볼 이름입니다." />
        <DatePicker label="만료일" defaultValue={new Date(2027, 1, 15)} help="최대 1년까지 정할 수 있습니다." />
        <RadioGroup legend="범위" name="sec-scope" defaultValue="read">
          <Radio value="read">읽기 전용</Radio>
          <Radio value="write">읽기와 쓰기</Radio>
        </RadioGroup>
      </Form>
      <PopupActions>
        <Button variant="outline" color="assistive">취소</Button>
        <Button type="submit" form="sec-create-form">만들기</Button>
      </PopupActions>
    </PopupSurface>
  );
}

import { Button, CopyField, Notice, PopupActions, PopupSurface, PopupTitle } from "@jiran/ds-react";

/* 비밀값은 만든 직후 한 번만 — 가린 채로도 전체 값이 복사된다. 본문에 알림과 필드가 있어 PopupBody(p) 대신 div.popup-body */
export default function Example() {
  return (
    <PopupSurface onClose={() => {}}>
      <PopupTitle>API 키를 만들었습니다</PopupTitle>
      <div className="popup-body">
        <Notice tone="warning" title="이 창을 닫으면 다시 볼 수 없습니다">지금 복사해 연동할 서비스에 넣으세요.</Notice>
        <CopyField secret label="비밀값" value="jsk_live_8c2e41f7a9b3d605e1" />
      </div>
      <PopupActions>
        <Button variant="outline" color="assistive">닫기</Button>
      </PopupActions>
    </PopupSurface>
  );
}

import { Button, PopupActions, PopupSurface, PopupTitle } from "@jiran/ds-react";

/* 재발급하면 옛 키가 바로 멈춘다 — alertdialog 로 묻고, 무엇이 끊기는지 적고, 취소를 앞에 둔다 */
export default function Example() {
  return (
    <PopupSurface danger onClose={() => {}} aria-describedby="sec-re-b">
      <PopupTitle>SIEM 연동 키를 재발급할까요?</PopupTitle>
      <div className="popup-body" id="sec-re-b">
        <p>지금 키는 바로 멈춥니다. 새 키를 SIEM 에 넣기 전까지 이벤트 전송이 끊깁니다.</p>
      </div>
      <PopupActions>
        <Button variant="outline" color="assistive">취소</Button>
        <Button color="negative">재발급</Button>
      </PopupActions>
    </PopupSurface>
  );
}

